        "content": "/* VibeKit components: a small base. Every class is a hook — restyle freely. */\n.vk-card { border: 1px solid color-mix(in srgb, currentColor 18%, transparent); border-radius: .5rem; display: grid; gap: .5rem; padding: .9rem 1rem; }\n.vk-kicker { font-size: .72rem; letter-spacing: .14em; opacity: .65; text-transform: uppercase; }\n.vk-hero { font-size: 1.35rem; font-weight: 600; line-height: 1.2; margin: 0; }\n.vk-unit { font-weight: 400; opacity: .7; }\n.vk-summary { margin: 0; opacity: .8; }\n.vk-facts { display: grid; gap: .25rem .75rem; grid-template-columns: max-content 1fr; margin: 0; }\n.vk-facts div { display: contents; }\n.vk-facts dt { opacity: .6; }\n.vk-facts dd { font-family: ui-monospace, monospace; margin: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.vk-id { font-family: ui-monospace, monospace; font-size: .8rem; opacity: .6; }\n.vk-error { color: #e07c7c; margin: 0; }\n.vk-json { font-size: .8rem; margin: 0; overflow-x: auto; }\n.vk-result-error .vk-kicker { color: #e07c7c; }\n.vk-table { border-collapse: collapse; width: 100%; }\n.vk-table th, .vk-table td { padding: .4rem .5rem; text-align: left; }\n.vk-table thead th { border-bottom: 1px solid color-mix(in srgb, currentColor 18%, transparent); font-weight: 500; opacity: .7; }\n.vk-num { font-variant-numeric: tabular-nums; text-align: right !important; }\n.vk-row-open { cursor: pointer; }\n.vk-row-open:hover { background: color-mix(in srgb, currentColor 6%, transparent); }\n.vk-approval-danger { border-color: #e07c7c; }\n.vk-actions { display: flex; gap: .5rem; justify-content: flex-end; }\n.vk-button { background: transparent; border: 1px solid currentColor; border-radius: .35rem; color: inherit; cursor: pointer; font: inherit; padding: .4rem .9rem; }\n.vk-button-primary { background: currentColor; }\n.vk-button-primary:not(:disabled) { color: Canvas; }\n.vk-button:disabled { cursor: not-allowed; opacity: .5; }\n"
